/// An error answer: HTTP status, the stable reason (API_KEY_INVALID, RATE_LIMIT_EXCEEDED…) and Retry-After seconds.
public struct NWaysError: Swift.Error, Sendable {
    public let status: Int
    public let reason: String?
    public let message: String
    public let retryAfter: Double?
    public let body: Data
}

/// The N-Ways Maps Platform API.
public final class NWaysClient: @unchecked Sendable {
    public let apiKey: String
    public let baseURL: URL
    public var headers: [String: String]
    let session: URLSession
    let decoder = JSONDecoder()
    let encoder = JSONEncoder()

    public init(apiKey: String, baseURL: URL = URL(string: "https://nways.ng")!, headers: [String: String] = [:], session: URLSession = .shared) {
        self.apiKey = apiKey
        self.baseURL = baseURL
        self.headers = headers
        self.session = session
    }

    static func escape(_ s: String) -> String {
        var allowed = CharacterSet.urlPathAllowed
        allowed.remove(charactersIn: "/?#")
        return s.addingPercentEncoding(withAllowedCharacters: allowed) ?? s
    }

    /// Sends one request and returns the raw answer.
    public func request(_ method: String, _ path: String, query: [String: String?] = [:], body: Data? = nil) async throws -> Data {
        var comps = URLComponents(url: baseURL, resolvingAgainstBaseURL: false)!
        comps.percentEncodedPath = comps.percentEncodedPath.trimmingCharacters(in: CharacterSet(charactersIn: "/")).isEmpty ? path : "/" + comps.percentEncodedPath.trimmingCharacters(in: CharacterSet(charactersIn: "/")) + path
        let items = query.compactMap { k, v in v.flatMap { $0.isEmpty ? nil : URLQueryItem(name: k, value: $0) } }.sorted { $0.name < $1.name }
        if !items.isEmpty { comps.queryItems = items }
        var req = URLRequest(url: comps.url!)
        req.httpMethod = method
        req.setValue("application/json", forHTTPHeaderField: "Accept")
        req.setValue(apiKey, forHTTPHeaderField: "X-NWays-Api-Key")
        req.setValue("nways-swift/\(nwaysClientVersion)", forHTTPHeaderField: "User-Agent")
        for (k, v) in headers { req.setValue(v, forHTTPHeaderField: k) }
        if let body {
            req.httpBody = body
            req.setValue("application/json", forHTTPHeaderField: "Content-Type")
        }
        let (data, response) = try await session.data(for: req)
        let http = response as? HTTPURLResponse
        let status = http?.statusCode ?? 0
        guard (200..<300).contains(status) else {
            let obj = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any]
            let env = obj?["error"] as? [String: Any]
            let reason = env?["reason"] as? String ?? obj?["code"] as? String
            let message = env?["message"] as? String ?? obj?["error"] as? String ?? "HTTP \(status)"
            let retry = (http?.value(forHTTPHeaderField: "Retry-After")).flatMap(Double.init)
            throw NWaysError(status: status, reason: reason, message: message, retryAfter: retry, body: data)
        }
        return data
    }

    /// A hosted map style (one map load) (GET /maps/v1/styles/{style}.json)
    public func getStyle(style: String, lang: String? = nil, format: String? = nil) async throws -> GetStyleResponse {
        return try decoder.decode(GetStyleResponse.self, from: try await request("GET", "/maps/v1/styles/\(Self.escape(style)).json", query: ["lang": lang, "format": format], body: nil))
    }

    /// The countries the map covers (GET /maps/v1/tiles/countries.json)
    public func getTileCountries() async throws -> GetTileCountriesResponse {
        return try decoder.decode(GetTileCountriesResponse.self, from: try await request("GET", "/maps/v1/tiles/countries.json", query: [:], body: nil))
    }

    /// Removed — whole-country archives aren't part of the platform (GET /maps/v1/tiles/{tileset}.pmtiles)
    public func getTileArchive(tileset: String) async throws -> JSONValue {
        return try decoder.decode(JSONValue.self, from: try await request("GET", "/maps/v1/tiles/\(Self.escape(tileset)).pmtiles", query: [:], body: nil))
    }

    /// One vector tile (GET /maps/v1/tiles/{tileset}/{z}/{x}/{y}.mvt)
    public func getTile(tileset: String, z: String, x: String, y: String) async throws -> Data {
        return try await request("GET", "/maps/v1/tiles/\(Self.escape(tileset))/\(Self.escape(z))/\(Self.escape(x))/\(Self.escape(y)).mvt", query: [:], body: nil)
    }

    /// One picture tile (GET /maps/v1/tiles/raster/{theme}/{z}/{x}/{y}.png)
    public func getRasterTile(theme: String, z: String, x: String, y: String) async throws -> Data {
        return try await request("GET", "/maps/v1/tiles/raster/\(Self.escape(theme))/\(Self.escape(z))/\(Self.escape(x))/\(Self.escape(y)).png", query: [:], body: nil)
    }

    /// Font glyphs for map labels (free) (GET /maps/v1/fonts/{stack}/{range}.pbf)
    public func getGlyphs(stack: String, range: String) async throws -> Data {
        return try await request("GET", "/maps/v1/fonts/\(Self.escape(stack))/\(Self.escape(range)).pbf", query: [:], body: nil)
    }

    /// A map image (GET /maps/v1/staticmap)
    public func getStaticMap(center: String? = nil, zoom: Double? = nil, size: String? = nil, scale: Int? = nil, theme: String? = nil, format: String? = nil, markers: [String]? = nil, path: [String]? = nil, signature: String? = nil) async throws -> Data {
        return try await request("GET", "/maps/v1/staticmap", query: ["center": center, "zoom": zoom.map { String($0) }, "size": size, "scale": scale.map { String($0) }, "theme": theme, "format": format, "markers": markers?.map { String(describing: $0) }.joined(separator: ","), "path": path?.map { String(describing: $0) }.joined(separator: ","), "signature": signature], body: nil)
    }

    /// Search for places, addresses and codes (GET /maps/v1/geocode)
    public func geocode(q: String, near: String? = nil, country: String? = nil, limit: Int? = nil, validate: Bool? = nil, lang: String? = nil, fields: String? = nil) async throws -> GeocodeResponse {
        return try decoder.decode(GeocodeResponse.self, from: try await request("GET", "/maps/v1/geocode", query: ["q": q, "near": near, "country": country, "limit": limit.map { String($0) }, "validate": validate.map { String($0) }, "lang": lang, "fields": fields], body: nil))
    }

    /// What's at a point (GET /maps/v1/reverse)
    public func reverseGeocode(lat: Double, lng: Double, radius: Double? = nil, lang: String? = nil, fields: String? = nil) async throws -> ReverseResponse {
        return try decoder.decode(ReverseResponse.self, from: try await request("GET", "/maps/v1/reverse", query: ["lat": String(lat), "lng": String(lng), "radius": radius.map { String($0) }, "lang": lang, "fields": fields], body: nil))
    }

    /// Any code people write as an address (GET /maps/v1/codes/{code})
    public func getCode(code: String, type: String? = nil, near: String? = nil, country: String? = nil, lang: String? = nil, fields: String? = nil) async throws -> CodeResponse {
        return try decoder.decode(CodeResponse.self, from: try await request("GET", "/maps/v1/codes/\(Self.escape(code))", query: ["type": type, "near": near, "country": country, "lang": lang, "fields": fields], body: nil))
    }

    /// Up to 100 codes of any kind at once (POST /maps/v1/codes/batch)
    public func getCodes(body: GetCodesRequest) async throws -> GetCodesResponse {
        return try decoder.decode(GetCodesResponse.self, from: try await request("POST", "/maps/v1/codes/batch", query: [:], body: try encoder.encode(body)))
    }

    /// A NIPOST postcode (alias of /codes/{code}) (GET /maps/v1/postcodes/{code})
    public func getPostcode(code: String, fields: String? = nil) async throws -> Postcode {
        return try decoder.decode(Postcode.self, from: try await request("GET", "/maps/v1/postcodes/\(Self.escape(code))", query: ["fields": fields], body: nil))
    }

